-- "AI önsöz" - maintainer's explicit ask: the real catalog (bulk-imported
-- from Open Library) has essentially zero books with a real `content`
-- description (confirmed: 0 of 125,926 real Turkish-language books on prod
-- have one). A separate `ai_summary` column, not reusing `content` - keeps
-- a genuine, honest distinction between "this is the publisher's own blurb"
-- (content) and "this was generated locally by an LLM" (ai_summary), shown
-- in the UI with a clear "AI tarafından oluşturulmuş" label rather than
-- silently passed off as authoritative back-cover copy. Generated by a
-- local/free Ollama model (qwen2.5:7b) - see scripts/generate-ai-summaries.mts -
-- deliberately prompted to only use real DB facts (title/author/category)
-- and avoid inventing specific plot details it has no grounding for.
ALTER TABLE book ADD COLUMN ai_summary TEXT NULL AFTER content;
